FormulaFieldDefinitions.FormulaFieldDefinition:
IF MID ({AC_MAST.AC_NAME},1,5) = 'ORDER' THEN
    {ROJ_MEL_DATA.VCH_NO} + ' - ' + {ROJ_MEL_DATA.AC_NAME}
ELSE IF MID ({AC_MAST.AC_NAME},1,5) = 'KASAR' THEN
    {ROJ_MEL_DATA.VCH_NO} + ' - KSR :' + {ROJ_MEL_DATA.AC_NAME}
ELSE IF {ROJ_MEL_DATA.BOOK_NAME} = 'MEMB_ENTRY' THEN
    {ROJ_MEL_DATA.VCH_NO} + ' - '+ {ROJ_MEL_DATA.MEMB_CODE} + ' - '+  {ROJ_MEL_DATA.AC_NAME}
ELSE IF {ROJ_MEL_DATA.AC_NAME} <> '' THEN
    {ROJ_MEL_DATA.VCH_NO} + ' - ' + {ROJ_MEL_DATA.AC_NAME}
ELSE
    {ROJ_MEL_DATA.VCH_NO} + ' - ' + {AC_MAST.AC_NAME}

IF ISNULL({ROJ_MEL_DATA.MEMB_CODE})  THEN
    IF MID ({AC_MAST.AC_NAME},1,5) = 'ORDER' THEN
        {ROJ_MEL_DATA.VCH_NO} + ' - ADV - ' + {ROJ_MEL_DATA.IT_DESC}
    ELSE
        {ROJ_MEL_DATA.VCH_NO} + ' - ' + {AC_MAST.AC_NAME}
ELSE
    {ROJ_MEL_DATA.VCH_NO} + ' - ' + {AC_MAST.AC_NAME}  + ' - ' + {ROJ_MEL_DATA.MEMB_CODE}

WhilePrintingRecords;
NumberVar OpenCrAmt;
NumberVar OpenDrAmt;
NumberVar ClosingBal;
ClosingBal := OpenDrAmt - OpenCrAmt + Sum ({@DrAmt}, {ROJ_MEL_DATA.VCH_DATE}, "daily") - Sum ({@CrAmt}, {ROJ_MEL_DATA.VCH_DATE}, "daily");
if ClosingBal > 0 then
(    OpenDrAmt := ClosingBal;
     OPenCrAmt := 0)
else
(    OpenCrAmt := Abs(ClosingBal);
     OPenDrAmt := 0;)

WhilePrintingRecords;
numbervar DailyOpBal := numbervar DailyOpBal + ({ROJ_MEL_DATA.CR_WT}-{ROJ_MEL_DATA.DR_AMT}) ;
numbervar DailyClBal := numbervar DailyClBal + ({ROJ_MEL_DATA.CR_AMT}-{ROJ_MEL_DATA.DR_AMT})

WhilePrintingRecords;
NumberVar OpenDrAmt;
NumberVar OpenCrAmt;
if {ROJ_MEL_DATA.VCH_DATE} <{@FromDate} and not InRepeatedGroupHeader then
    if Sum ({@OpeningBal}) > 0 then
        OpenCrAmt := Sum ({@OpeningBal})
    else
        OpenDrAmt := Abs(Sum ({@OpeningBal}))

WhilePrintingRecords;
NumberVar OpenCrAmt := 0;
NumberVar OpenDrAmt := 0;
numbervar DailyOpBal := {@OpenCashAmt} ;
numbervar DailyClBal := {@OpenCashAmt}
